from collections import deque
import math
import random

A_TURN_LEFT = 0
A_TURN_RIGHT = 1
A_FORWARD = 2
A_PICKUP = 3
A_DROP = 4
A_TOGGLE = 5
A_DONE = 6

# image coords: x=0..6 left->right, y=0..6 far->near. Agent at (3,6) facing "up" (toward smaller y).
AG_X, AG_Y = 3, 6
W, H = 7, 7

def in_bounds(x, y):
    return 0 <= x < W and 0 <= y < H

def cell_obj(img, x, y):
    # returns tuple (obj, color, state) or None for unseen
    c = img[x][y]
    if c is None:
        return None
    return tuple(c)

def is_unseen(img, x, y):
    c = img[x][y]
    return (c is None) or (c[0] == 0)

def is_traversable(img, x, y):
    # whether the agent can move into this cell (forward) based on current view
    # allow floor-like cells (1 or 3), goal (8), open door (4,state==0)
    if not in_bounds(x, y):
        return False
    c = img[x][y]
    if c is None:
        return False
    obj, col, st = c
    if obj == 3 or obj == 1 or obj == 8:  # floor-like or empty or goal
        return True
    if obj == 4 and st == 0:  # door open
        return True
    # note: keys (5), balls (6), boxes(7), closed/locked doors block forward
    return False

def find_all(img, predicate):
    res = []
    for x in range(W):
        for y in range(H):
            if is_unseen(img, x, y):
                continue
            if predicate(img[x][y]):
                res.append((x, y))
    return res

def find_keys(img):
    return find_all(img, lambda c: c[0] == 5)

def find_balls(img):
    return find_all(img, lambda c: c[0] == 6)

def find_doors(img):
    return find_all(img, lambda c: c[0] == 4)

def door_state_color(img, x, y):
    c = img[x][y]
    if c is None:
        return None, None
    obj, col, st = c
    return st, col

def neighbors_4(x, y):
    return [(x, y-1), (x+1, y), (x, y+1), (x-1, y)]

def bfs_to_targets(img, targets, allow_current=True):
    # BFS on visible grid from agent position to any of target positions (set)
    # Traversable cells: is_traversable OR the target cell itself (so we can reach next to object if needed)
    tgtset = set(targets)
    start = (AG_X, AG_Y)
    q = deque([start])
    prev = {start: None}
    while q:
        cur = q.popleft()
        if cur in tgtset:
            # reconstruct path
            path = []
            p = cur
            while p is not None:
                path.append(p)
                p = prev[p]
            path.reverse()
            return path  # includes start and goal
        for nx, ny in neighbors_4(cur[0], cur[1]):
            if not in_bounds(nx, ny):
                continue
            if (nx, ny) in prev:
                continue
            # allow stepping into traversable cells; also allow stepping into target cells even if not traversable
            if (nx, ny) in tgtset:
                prev[(nx, ny)] = cur
                q.append((nx, ny))
            elif is_traversable(img, nx, ny):
                prev[(nx, ny)] = cur
                q.append((nx, ny))
    return None

def find_reachable_adjacent_positions(img, target_pos):
    # return list of positions (cells) agent can stand on such that target_pos is directly in front of agent (in agent's view)
    # since agent's facing always "up" in the image, being "in front" means agent at (tx, ty+1) facing up and the target at (tx, ty)
    tx, ty = target_pos
    # position to stand so that target is in front (relative to current view orientation) is (tx, ty+1)
    ax, ay = tx, ty + 1
    if in_bounds(ax, ay) and not is_unseen(img, ax, ay) and is_traversable(img, ax, ay):
        return [(ax, ay)]
    # but sometimes we might want to stand left/right/down and rotate so that target is in front; we can consider any adjacent cell where
    # there exists an orientation that would make target be in front. Because our orientation is always "up" in the image, that corresponds
    # to standing in a cell that is one cell below the target in the world of the current view. So the safe candidate is just (tx,ty+1).
    return []

def next_action_towards(img, next_cell):
    # Decide an immediate action to move from agent cell to next_cell.
    nx, ny = next_cell
    dx = nx - AG_X
    dy = ny - AG_Y
    # relative to current orientation (agent faces up): forward is (0,-1), left (-1,0), right (1,0), back (0,1)
    if dx == 0 and dy == -1:
        return A_FORWARD
    if dx == -1 and dy == 0:
        return A_TURN_LEFT
    if dx == 1 and dy == 0:
        return A_TURN_RIGHT
    if dx == 0 and dy == 1:
        # need to rotate twice; start with a turn (choose left)
        return A_TURN_LEFT
    # fallback
    return A_TURN_RIGHT

def find_empty_cells(img):
    # consider cells with object==1 or 3 as empty/traversable for dropping keys (we need the cell in front to be empty).
    res = []
    for x in range(W):
        for y in range(H):
            if is_unseen(img, x, y):
                continue
            c = img[x][y]
            obj, col, st = c
            if obj == 1 or obj == 3:
                res.append((x, y))
    return res

def decide_action(obs, memory):
    img = obs['image']
    last = obs.get('last_action', None)

    # current carrying status using agent cell (3,6)
    carried = None
    acell = img[AG_X][AG_Y]
    if acell is not None:
        if acell[0] == 5:
            carried = ('key', acell[1])  # color code
        elif acell[0] == 6:
            carried = ('ball', None)
        else:
            carried = None

    # quick observable lists
    keys = find_keys(img)
    balls = find_balls(img)
    doors = find_doors(img)

    # Helper: is the cell immediately in front containing something specific?
    front = img[AG_X][AG_Y - 1] if in_bounds(AG_X, AG_Y - 1) else None
    front_obj = None
    front_color = None
    front_state = None
    if front is not None:
        front_obj, front_color, front_state = front

    # 1) If the ball is directly in front and we are allowed to pick it up -> pickup
    if front is not None and front_obj == 6:
        # if carrying key we MUST drop it before picking up the ball
        if carried is None or carried[0] != 'key':
            return A_PICKUP
        else:
            # we are carrying key and ball is in front; need to drop key somewhere first
            # look for any adjacent empty cell we can face and drop onto (i.e. stand such that front cell is empty)
            # A practical choice: if the cell two-in-front is empty, step forward (if safe), drop, then step back to pick ball
            two_front_coords = (AG_X, AG_Y - 2)
            if in_bounds(*two_front_coords):
                c2 = img[two_front_coords[0]][two_front_coords[1]]
                if c2 is not None and (c2[0] == 1 or c2[0] == 3):
                    # check forward is not blocked (can't forward if front is ball): we cannot move forward because ball blocks forward.
                    # Instead, rotate to side and drop on side if possible: check left or right cell in front from a neighboring standing position
                    pass
            # fallback: try to find any empty cell, navigate to it, and drop there
            # We'll handle dropping below in main logic
    # 2) If facing a door in front that is closed or locked and toggling is useful, do it
    if front is not None and front_obj == 4:
        st = front_state
        dcol = front_color
        # if locked and we carry matching key -> toggle (unlock)
        if st == 2 and carried is not None and carried[0] == 'key' and carried[1] == dcol:
            return A_TOGGLE
        # if closed (unlocked) -> open
        if st == 1:
            return A_TOGGLE
        # otherwise (locked but wrong key or no key) don't toggle; try to find key

    # If carrying key and we see a locked door of same color anywhere, navigate to it and unlock
    if carried is not None and carried[0] == 'key':
        my_key_color = carried[1]
        # find locked doors of same color
        target_locked = []
        for (dx_, dy_) in doors:
            c = img[dx_][dy_]
            if c is None:
                continue
            obj, col, st = c
            if st == 2 and col == my_key_color:
                target_locked.append((dx_, dy_))
        if target_locked:
            # plan to reach the door cell (standing in front of it) and then unlock
            # for each locked door, pick reachable adjacent position (standing below it in current view)
            best_path = None
            best_target = None
            for dpos in target_locked:
                # position to stand so door is in front: (dx, dy+1)
                tx, ty = dpos
                stand = (tx, ty + 1)
                if not in_bounds(*stand):
                    continue
                if is_unseen(img, stand[0], stand[1]):
                    continue
                if not is_traversable(img, stand[0], stand[1]):
                    continue
                path = bfs_to_targets(img, [stand])
                if path is not None:
                    if best_path is None or len(path) < len(best_path):
                        best_path = path
                        best_target = (dpos, stand)
            if best_path is not None:
                # if we're already at the stand and door in front is locked -> toggle
                if best_path[-1] == (AG_X, AG_Y):
                    # ensure front is that door (sanity)
                    fx, fy = AG_X, AG_Y - 1
                    if in_bounds(fx, fy):
                        f = img[fx][fy]
                        if f is not None and f[0] == 4 and f[2] == 2 and f[1] == my_key_color:
                            return A_TOGGLE
                    # if not exactly in front, just try to rotate to face the door: turn to get it in front
                    # We can attempt small rotations to align
                    # Find where the door appears in view; if to left/right, turn accordingly
                    doorpos = best_target[0]
                    dx_rel = doorpos[0] - AG_X
                    dy_rel = doorpos[1] - AG_Y
                    # If door is left in the view
                    if dx_rel < 0:
                        return A_TURN_LEFT
                    if dx_rel > 0:
                        return A_TURN_RIGHT
                    # if behind
                    return A_TURN_LEFT
                # else follow path: take the next step on the path
                if len(best_path) >= 2:
                    next_cell = best_path[1]
                    return next_action_towards(img, next_cell)
        # if no matching locked door visible, we should try to find ball or explore to find door/ball
        # If ball visible: before going to ball we must drop key somewhere safe
        if balls:
            # we will find an empty cell to drop key first
            empties = find_empty_cells(img)
            # prefer empties that are reachable
            best_path = None
            best_empty = None
            for e in empties:
                # we need to stand such that cell in front is that empty cell; i.e., stand at (ex, ey+1)
                ex, ey = e
                stand = (ex, ey + 1)
                if not in_bounds(*stand):
                    continue
                if is_unseen(img, stand[0], stand[1]):
                    continue
                if not is_traversable(img, stand[0], stand[1]):
                    continue
                path = bfs_to_targets(img, [stand])
                if path is not None:
                    if best_path is None or len(path) < len(best_path):
                        best_path = path
                        best_empty = (e, stand)
            if best_path is not None:
                # if already standing at desired stand and the cell in front is empty -> drop
                if best_path[-1] == (AG_X, AG_Y):
                    fx, fy = AG_X, AG_Y - 1
                    if in_bounds(fx, fy):
                        f = img[fx][fy]
                        if f is not None and (f[0] == 1 or f[0] == 3):
                            return A_DROP
                    # else rotate to make that empty in front
                    ex, ey = best_empty[0]
                    # where is that empty relative to us?
                    dx_rel = ex - AG_X
                    dy_rel = ey - AG_Y
                    # empty is in front-other cell; Depending on relative location, rotate
                    if dx_rel < 0:
                        return A_TURN_LEFT
                    if dx_rel > 0:
                        return A_TURN_RIGHT
                    return A_TURN_LEFT
                # else follow path towards stand
                if len(best_path) >= 2:
                    next_cell = best_path[1]
                    return next_action_towards(img, next_cell)
            # if no empty found or reachable: fallback to exploring (below)
    # If not carrying a key:
    if carried is None or (carried[0] != 'key'):
        # If a key is visible: go to it and pick it up
        if keys:
            # target the first visible key (closest by BFS)
            best_path = None
            best_keypos = None
            for kpos in keys:
                # we need to stand in front of key to pick it up: stand = (kx, ky+1)
                kx, ky = kpos
                stand = (kx, ky + 1)
                if not in_bounds(*stand):
                    continue
                if is_unseen(img, stand[0], stand[1]):
                    continue
                if not is_traversable(img, stand[0], stand[1]):
                    continue
                path = bfs_to_targets(img, [stand])
                if path is not None:
                    if best_path is None or len(path) < len(best_path):
                        best_path = path
                        best_keypos = (kpos, stand)
            if best_path is not None:
                # if we are standing at stand and key is in front -> pickup
                if best_path[-1] == (AG_X, AG_Y):
                    fx, fy = AG_X, AG_Y - 1
                    if in_bounds(fx, fy):
                        f = img[fx][fy]
                        if f is not None and f[0] == 5:
                            return A_PICKUP
                    # else rotate to face it
                    kpos = best_keypos[0]
                    dx_rel = kpos[0] - AG_X
                    if dx_rel < 0:
                        return A_TURN_LEFT
                    if dx_rel > 0:
                        return A_TURN_RIGHT
                    return A_TURN_LEFT
                # else move along path
                if len(best_path) >= 2:
                    return next_action_towards(img, best_path[1])
        # If no key visible, but ball visible: go to ball (but ensure we don't carry a key)
        if balls:
            # go pick ball (we are not carrying a key so fine)
            best_path = None
            best_ball = None
            for bpos in balls:
                bx, by = bpos
                stand = (bx, by + 1)
                if not in_bounds(*stand):
                    continue
                if is_unseen(img, stand[0], stand[1]):
                    continue
                if not is_traversable(img, stand[0], stand[1]):
                    continue
                path = bfs_to_targets(img, [stand])
                if path is not None:
                    if best_path is None or len(path) < len(best_path):
                        best_path = path
                        best_ball = (bpos, stand)
            if best_path is not None:
                # if at stand and ball in front -> pickup
                if best_path[-1] == (AG_X, AG_Y):
                    fx, fy = AG_X, AG_Y - 1
                    if in_bounds(fx, fy):
                        f = img[fx][fy]
                        if f is not None and f[0] == 6:
                            return A_PICKUP
                    # else rotate to face ball
                    bpos = best_ball[0]
                    dx_rel = bpos[0] - AG_X
                    if dx_rel < 0:
                        return A_TURN_LEFT
                    if dx_rel > 0:
                        return A_TURN_RIGHT
                    return A_TURN_LEFT
                # else follow path
                if len(best_path) >= 2:
                    return next_action_towards(img, best_path[1])

    # If none of the above applies, we try to open closed doors that block immediate forward progress
    # If forward is a closed door and toggleable without key -> toggle
    if front is not None and front_obj == 4 and front_state == 1:
        return A_TOGGLE

    # Exploration / scanning behavior:
    # Prefer moving forward if safe; otherwise rotate to the right to scan
    fwd_x, fwd_y = AG_X, AG_Y - 1
    if in_bounds(fwd_x, fwd_y) and not is_unseen(img, fwd_x, fwd_y):
        if is_traversable(img, fwd_x, fwd_y):
            return A_FORWARD
    # if forward not traversable, try turning right to explore
    return A_TURN_RIGHT

def controller(obs, memory) -> int:
    # memory can be used to store nothing or minor info; we keep it simple and stateless for robustness.
    # But ensure memory exists
    if memory is None:
        memory = {}
    try:
        action = decide_action(obs, memory)
        # store last chosen for debugging if desired
        memory['last_choice'] = action
        return int(action)
    except Exception:
        # safe fallback
        return A_TURN_RIGHT
