from collections import deque
import math
import random
import itertools

# Actions
A_TURN_LEFT = 0
A_TURN_RIGHT = 1
A_FORWARD = 2
A_PICKUP = 3
A_DROP = 4
A_TOGGLE = 5
A_DONE = 6

# Image geometry
W, H = 7, 7
AG_X, AG_Y = 3, 6  # agent always at (3,6) facing "up" in the provided view

def in_bounds(x, y):
    return 0 <= x < W and 0 <= y < H

def is_unseen(img, x, y):
    c = img[x][y]
    return (c is None) or (c[0] == 0)

def cell(img, x, y):
    return img[x][y] if in_bounds(x, y) else None

def is_traversable(img, x, y):
    # Traversable for movement: floor (3), empty (1), goal (8), open door (4 with state 0)
    if not in_bounds(x, y):
        return False
    c = img[x][y]
    if c is None:
        return False
    obj, col, st = c
    if obj in (1, 3, 8):
        return True
    if obj == 4 and st == 0:
        return True
    return False

def find_all(img, predicate):
    res = []
    for x in range(W):
        for y in range(H):
            if is_unseen(img, x, y):
                continue
            if predicate(img[x][y]):
                res.append((x, y))
    return res

def find_keys(img):
    return find_all(img, lambda c: c[0] == 5)

def find_balls(img):
    return find_all(img, lambda c: c[0] == 6)

def find_doors(img):
    return find_all(img, lambda c: c[0] == 4)

def neighbors_4(pos):
    x, y = pos
    for nx, ny in ((x, y-1), (x+1, y), (x, y+1), (x-1, y)):
        if in_bounds(nx, ny):
            yield (nx, ny)

def bfs_to_targets(img, targets, allow_unseen_target=False):
    # BFS on visible grid from agent position to any of target positions.
    # Traversable nodes are those is_traversable. However we allow stepping into target
    # even if it's not traversable (so long as allow_unseen_target=True or target visible).
    tgtset = set(targets)
    start = (AG_X, AG_Y)
    q = deque([start])
    prev = {start: None}
    while q:
        cur = q.popleft()
        if cur in tgtset:
            # reconstruct path
            path = []
            p = cur
            while p is not None:
                path.append(p)
                p = prev[p]
            path.reverse()
            return path
        for nb in neighbors_4(cur):
            if nb in prev:
                continue
            nx, ny = nb
            if nb in tgtset:
                # allow target even if unseen (only if flagged)
                if not is_unseen(img, nx, ny) or allow_unseen_target:
                    prev[nb] = cur
                    q.append(nb)
            elif is_traversable(img, nx, ny):
                prev[nb] = cur
                q.append(nb)
    return None

def pos_equal(a, b):
    return a[0] == b[0] and a[1] == b[1]

def next_action_towards(img, next_cell):
    # Decide immediate action to go from agent (3,6) to next_cell.
    nx, ny = next_cell
    dx = nx - AG_X
    dy = ny - AG_Y
    # Relative to current orientation (facing up): forward (0,-1), left (-1,0), right (1,0), back (0,1)
    if dx == 0 and dy == -1:
        # ensure forward is not blocked
        front = cell(img, AG_X, AG_Y - 1)
        if front is not None and front[0] in (2, 4, 5, 6, 7):  # wall, door (closed/locked), key, ball, box block forward
            # if it's a closed/unlockable door, try toggle if possible
            if front[0] == 4:
                # if door is openable/unlockable, prefer toggle
                if front[2] in (0,1,2):
                    return A_TOGGLE
            # otherwise rotate to scan
            return A_TURN_RIGHT
        return A_FORWARD
    if dx == -1 and dy == 0:
        return A_TURN_LEFT
    if dx == 1 and dy == 0:
        return A_TURN_RIGHT
    if dx == 0 and dy == 1:
        # need to face backward; start rotating (choose left)
        return A_TURN_LEFT
    # fallback
    return random.choice([A_TURN_LEFT, A_TURN_RIGHT])

def carrying_from_image(img):
    ac = img[AG_X][AG_Y]
    if ac is None:
        return None
    if ac[0] == 5:
        return ('key', ac[1])
    if ac[0] == 6:
        return ('ball', None)
    return None

def stands_for_target(target):
    # Given a target cell (tx,ty) that we want to interact with (pick/unlock/drop),
    # the natural standing cell is (tx, ty+1) so the agent's "front" (x, y-1) = target.
    tx, ty = target
    return (tx, ty + 1)

def find_reachable_stands_for_targets(img, targets):
    stands = []
    for t in targets:
        s = stands_for_target(t)
        if not in_bounds(*s):
            continue
        # we require stand to be visible and traversable
        if is_unseen(img, s[0], s[1]):
            continue
        if not is_traversable(img, s[0], s[1]):
            continue
        stands.append((t, s))
    # find shortest reachable by BFS
    best_path = None
    best_pair = None
    for t, s in stands:
        path = bfs_to_targets(img, [s])
        if path is not None:
            if best_path is None or len(path) < len(best_path):
                best_path = path
                best_pair = (t, s, path)
    return best_pair  # (target, stand, path) or None

def find_any_empty_stand(img):
    # find any (target empty cell e) such that stand = (ex,ey+1) is traversable and reachable.
    empties = []
    for x in range(W):
        for y in range(H):
            if is_unseen(img, x, y):
                continue
            c = img[x][y]
            if c is None:
                continue
            obj = c[0]
            if obj in (1, 3):  # empty or floor
                empties.append((x, y))
    for e in empties:
        s = stands_for_target(e)
        if not in_bounds(*s):
            continue
        if is_unseen(img, s[0], s[1]):
            continue
        if not is_traversable(img, s[0], s[1]):
            continue
        path = bfs_to_targets(img, [s])
        if path is not None:
            return (e, s, path)
    return None

def find_front_cell(img):
    fx, fy = AG_X, AG_Y - 1
    if not in_bounds(fx, fy):
        return None, None
    c = img[fx][fy]
    if c is None:
        return None, None
    return c, (fx, fy)

def find_explore_targets(img):
    # find traversable cells that are adjacent to at least one unseen cell -> good to step to reveal
    targets = []
    for x in range(W):
        for y in range(H):
            if is_unseen(img, x, y):
                continue
            if not is_traversable(img, x, y):
                continue
            # check adjacent unseen
            adjacent_unseen = False
            for nx, ny in neighbors_4((x, y)):
                if is_unseen(img, nx, ny):
                    adjacent_unseen = True
                    break
            if adjacent_unseen:
                targets.append((x, y))
    # Return nearest reachable target path
    best_path = None
    best_target = None
    for t in targets:
        path = bfs_to_targets(img, [t], allow_unseen_target=False)
        if path is not None:
            if best_path is None or len(path) < len(best_path):
                best_path = path
                best_target = t
    if best_path is not None:
        return best_target, best_path
    return None, None

def decide_action(obs, memory):
    img = obs['image']
    last_action_executed = obs.get('last_action', None)

    carried = carrying_from_image(img)

    # Visible objects
    keys = find_keys(img)
    balls = find_balls(img)
    doors = find_doors(img)

    # Quick info about front cell
    front_cell, front_pos = find_front_cell(img)
    if front_cell is not None:
        front_obj, front_col, front_state = front_cell
    else:
        front_obj = None
        front_col = None
        front_state = None

    # 1) If front is a matching locked door and we have matching key -> toggle (unlock)
    if front_obj == 4 and front_state == 2 and carried is not None and carried[0] == 'key' and carried[1] == front_col:
        return A_TOGGLE

    # 2) If front is a closed door (unlocked) -> open it
    if front_obj == 4 and front_state == 1:
        return A_TOGGLE

    # 3) If front is ball and we are allowed to pickup (not carrying key) -> pickup
    if front_obj == 6:
        if carried is None or carried[0] != 'key':
            return A_PICKUP
